// Pairing is generated by the desktop installer, never included in a release.
try { importScripts('local-connection.js'); } catch {}
const MoriLocalBridge = (() => {
  const endpoint = 'http://127.0.0.1:47891/mori/v1';
  function configured() {
    return typeof self !== 'undefined' && self.MoriLocalConnection?.endpoint === endpoint &&
      /^[a-f0-9]{64}$/.test(self.MoriLocalConnection?.token || '');
  }
  async function request(message) {
    if (!configured()) return null;
    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), 20000);
    try {
      const response = await fetch(endpoint, {method:'POST', credentials:'omit', cache:'no-store',
        redirect:'error', signal:controller.signal,
        headers:{'Content-Type':'application/json','X-Mori-Token':self.MoriLocalConnection.token},
        body:JSON.stringify(message)});
      if (!response.ok) return {ok:false,code:'LOCAL_CONNECTION_REJECTED',error:'本机备用连接未配对。请在 Nook 的浏览器收藏设置中重新连接，然后重新加载插件。'};
      const reply = await response.json();
      if (!reply || typeof reply.ok !== 'boolean') throw Error('Invalid local reply');
      return {...reply, transport:'local'};
    } catch {
      // Do not retry a write whose response was lost: it may already be saved.
      return {ok:false,code:'LOCAL_CONNECTION_UNAVAILABLE',error:['folders','bridgeStatus','extensionControl'].includes(message.action)
        ? '请先打开 Nook，再重试收藏。备用连接仅在软件运行时可用。'
        : '未收到 Nook 的收藏结果。请先检查图库中是否已保存，再重试，避免重复收藏。'};
    } finally { clearTimeout(timeout); }
  }
  return {configured, request};
})();
